// Enum numérico: sem valores explícitos, a numeração começa em 0
enum DiaUtilEnum {
  Segunda,
  Terca,
  Quarta,
}

console.log(DiaUtilEnum.Segunda); // 0
console.log(DiaUtilEnum.Quarta);  // 2

// Com valores explícitos, o número é o que escrever
enum CodigoHttpEnum {
  Ok = 200,
  NaoAutorizado = 401,
  NaoEncontrado = 404,
}

console.log(CodigoHttpEnum.NaoEncontrado); // 404

// A numeração automática retoma a partir do último valor explícito
enum PrioridadeEnum {
  Baixa = 1,
  Media,
  Alta,
}

console.log(PrioridadeEnum.Media); // 2
console.log(PrioridadeEnum.Alta);  // 3

// O nome do enum serve de tipo e de valor ao mesmo tempo
const prioridadeAtual: PrioridadeEnum = PrioridadeEnum.Alta;
console.log(prioridadeAtual); // 3

// Num enum de string, todos os membros têm de ter valor explícito
enum EstadoEncomendaEnum {
  Pendente = "PENDENTE",
  Enviada = "ENVIADA",
  Entregue = "ENTREGUE",
}

function descreverEncomenda(estado: EstadoEncomendaEnum): string {
  return `A encomenda está ${estado}`;
}

console.log(descreverEncomenda(EstadoEncomendaEnum.Enviada)); // "A encomenda está ENVIADA"

// O enum é nominal: a string crua não serve, mesmo sendo igual ao valor
// @ts-expect-error o tipo "ENVIADA" não é atribuível a EstadoEncomendaEnum
descreverEncomenda("ENVIADA");

// Guardar o valor numa base de dados dá uma linha legível
const paraGravar: string = EstadoEncomendaEnum.Entregue;
console.log(paraGravar); // "ENTREGUE"

enum NivelLogEnum {
  Aviso = "AVISO",
  Erro = "ERRO",
}

// JavaScript gerado (simplificado):
//
// var NivelLogEnum;
// (function (NivelLogEnum) {
//     NivelLogEnum["Aviso"] = "AVISO";
//     NivelLogEnum["Erro"] = "ERRO";
// })(NivelLogEnum || (NivelLogEnum = {}));
//
// Repare que sobra um objeto real no ficheiro compilado.

// Como o objeto existe em runtime, pode ser inspecionado como qualquer outro
console.log(Object.keys(NivelLogEnum));   // ["Aviso", "Erro"]
console.log(Object.values(NivelLogEnum)); // ["AVISO", "ERRO"]

// E pode percorrer os valores sem escrever a lista uma segunda vez
for (const nivel of Object.values(NivelLogEnum)) {
  console.log(`nível disponível: ${nivel}`);
}

enum DirecaoEnum {
  Cima = 0,
  Baixo = 1,
}

// JavaScript gerado (simplificado):
//
// var DirecaoEnum;
// (function (DirecaoEnum) {
//     DirecaoEnum[DirecaoEnum["Cima"] = 0] = "Cima";
//     DirecaoEnum[DirecaoEnum["Baixo"] = 1] = "Baixo";
// })(DirecaoEnum || (DirecaoEnum = {}));
//
// Cada linha faz duas atribuições: nome para número e número para nome.

console.log(DirecaoEnum.Cima);                    // 0
console.log(DirecaoEnum[DirecaoEnum.Cima]);       // "Cima"
console.log(Object.keys(DirecaoEnum));            // ["0", "1", "Cima", "Baixo"]

enum TemaEnum {
  Claro = "CLARO",
  Escuro = "ESCURO",
}

// Nos enums de string não há mapeamento inverso: só existem as chaves dos membros
// @ts-expect-error a propriedade "CLARO" não existe em typeof TemaEnum
console.log(TemaEnum["CLARO"]);

const enum UnidadeConstEnum {
  Metro = "m",
  Quilometro = "km",
}

const distanciaTexto = `12 ${UnidadeConstEnum.Quilometro}`;
console.log(distanciaTexto); // "12 km"

// JavaScript gerado (simplificado):
//
// const distanciaTexto = `12 ${"km" /* UnidadeConstEnum.Quilometro */}`;
//
// Não sobra objeto nenhum: o compilador substitui cada acesso pelo valor.
// O preço é que, sem o objeto, nada consegue percorrer os membros em runtime
// e qualquer ferramenta que compile ficheiro a ficheiro fica sem a informação
// de que precisa para fazer essa substituição.

// Versão mínima: só o tipo, sem uma linha de JavaScript gerado
type EstadoPagamento = "pendente" | "pago" | "reembolsado";

function podeReembolsar(estado: EstadoPagamento): boolean {
  return estado === "pago";
}

console.log(podeReembolsar("pago")); // true

// Quando também precisa dos valores em runtime, acrescente um objeto as const
const EstadoPagamentoValores = {
  Pendente: "pendente",
  Pago: "pago",
  Reembolsado: "reembolsado",
} as const;

// O tipo passa a ser derivado do objeto, em vez de escrito duas vezes
type EstadoPagamentoDerivado =
  (typeof EstadoPagamentoValores)[keyof typeof EstadoPagamentoValores];
// "pendente" | "pago" | "reembolsado"

const todosOsEstados: EstadoPagamentoDerivado[] = Object.values(EstadoPagamentoValores);
console.log(todosOsEstados); // ["pendente", "pago", "reembolsado"]

console.log(podeReembolsar(EstadoPagamentoValores.Pago)); // true

// Com união de literais, o valor que chega do exterior já é o valor final
type MetodoPagamento = "cartao" | "mbway" | "transferencia";

function taxaDoMetodo(metodo: MetodoPagamento): number {
  return metodo === "cartao" ? 0.9 : 0;
}

const metodoBruto: string = "mbway";
if (metodoBruto === "cartao" || metodoBruto === "mbway" || metodoBruto === "transferencia") {
  console.log(taxaDoMetodo(metodoBruto)); // 0
}

// Com enum, o mesmo valor tem de ser convertido antes de poder ser usado
enum MetodoPagamentoEnum {
  Cartao = "cartao",
  MbWay = "mbway",
  Transferencia = "transferencia",
}

const outroBruto: string = "mbway";
const metodoComoEnum = outroBruto as MetodoPagamentoEnum;
console.log(metodoComoEnum === MetodoPagamentoEnum.MbWay); // true

// A conversão não valida nada: isto passa na compilação e é lixo em runtime
const metodoInvalido = "paypal" as MetodoPagamentoEnum;
console.log(metodoInvalido === MetodoPagamentoEnum.MbWay); // false

