enum EstadoTarefaEx {
  Pendente = "PENDENTE",
  EmCurso = "EM_CURSO",
  Concluida = "CONCLUIDA",
}

function etiquetaTarefa(estado: EstadoTarefaEx): string {
  if (estado === EstadoTarefaEx.Pendente) {
    return "Por começar";
  }
  if (estado === EstadoTarefaEx.EmCurso) {
    return "Em curso";
  }
  return "Terminada";
}

console.log(etiquetaTarefa(EstadoTarefaEx.EmCurso));   // "Em curso"
console.log(etiquetaTarefa(EstadoTarefaEx.Concluida)); // "Terminada"
console.log(Object.values(EstadoTarefaEx));            // ["PENDENTE", "EM_CURSO", "CONCLUIDA"]

const PrioridadeEx = {
  Baixa: 1,
  Media: 2,
  Alta: 3,
} as const;

type PrioridadeEx = (typeof PrioridadeEx)[keyof typeof PrioridadeEx];
// 1 | 2 | 3

function listarPrioridades(): PrioridadeEx[] {
  return Object.values(PrioridadeEx);
}

function acimaDe(minimo: PrioridadeEx): PrioridadeEx[] {
  return listarPrioridades().filter((p) => p > minimo);
}

console.log(listarPrioridades());         // [1, 2, 3]
console.log(acimaDe(PrioridadeEx.Baixa)); // [2, 3]

// @ts-expect-error 4 não pertence à união 1 | 2 | 3
const foraDeEscala: PrioridadeEx = 4;
console.log(foraDeEscala);

enum CodigoErroEx {
  NaoEncontrado = 404,
  Conflito = 409,
  Interno = 500,
}

function nomesDoEnum(objeto: object): string[] {
  return Object.keys(objeto).filter((chave) => Number.isNaN(Number(chave)));
}

function valoresDoEnum(objeto: object): number[] {
  return Object.keys(objeto)
    .map((chave) => Number(chave))
    .filter((n) => !Number.isNaN(n));
}

console.log(Object.keys(CodigoErroEx));
// ["404", "409", "500", "NaoEncontrado", "Conflito", "Interno"]
console.log(nomesDoEnum(CodigoErroEx));
// ["NaoEncontrado", "Conflito", "Interno"]
console.log(valoresDoEnum(CodigoErroEx));
// [404, 409, 500]
console.log(CodigoErroEx[CodigoErroEx.Conflito]);
// "Conflito"

const ESTADOS_SESSAO = ["anonimo", "autenticado", "expirado"] as const;

type EstadoSessao = (typeof ESTADOS_SESSAO)[number];
// "anonimo" | "autenticado" | "expirado"

function eEstadoSessao(valor: unknown): valor is EstadoSessao {
  return typeof valor === "string" && (ESTADOS_SESSAO as readonly string[]).includes(valor);
}

function lerEstado(bruto: unknown): EstadoSessao {
  if (!eEstadoSessao(bruto)) {
    throw new Error(`Estado de sessão desconhecido: ${String(bruto)}`);
  }
  return bruto;
}

// O Record obriga a cobrir todos os membros: falta um e o compilador reclama
const ETIQUETAS_SESSAO: Record<EstadoSessao, string> = {
  anonimo: "Visitante",
  autenticado: "Sessão ativa",
  expirado: "Sessão expirada",
};

console.log(eEstadoSessao("banido"));                  // false
console.log(lerEstado("autenticado"));                 // "autenticado"
console.log(ETIQUETAS_SESSAO[lerEstado("expirado")]);  // "Sessão expirada"
console.log(ESTADOS_SESSAO.length);                    // 3
